-- Node runs: every status, model columns, and values Swift's enums don't know.



-- expires_at is in the past on purpose: nothing but the maintenance job looks at it.

-- A run with events: Swift's store fails on any row (Module's errEventRows).

-- wf_spd's spend. Both today and tomorrow, and both months, so a run that crosses
-- midnight UTC reads the same numbers from whichever day it asks about.
SELECT 'tenant:F10F0000-0000-4000-8000-0000000000B3', 'day', d::date, 12345, 7
FROM (VALUES ((now() AT TIME ZONE 'UTC')::date), ((now() AT TIME ZONE 'UTC')::date + 1)) AS v(d);
SELECT DISTINCT 'tenant:F10F0000-0000-4000-8000-0000000000B3', 'month', date_trunc('month', d)::date, 54321::bigint, 9::bigint
FROM (VALUES ((now() AT TIME ZONE 'UTC')::date), ((now() AT TIME ZONE 'UTC')::date + 1)) AS v(d);


-- Columns the scenarios can't compare raw. A rotated secret is random, so only its
-- shape is compared. A template run's name ends in a random id.
CREATE VIEW parity_workflow_webhooks AS
SELECT id, tenant_id, workflow_id, length(secret_ciphertext) AS ciphertext_bytes, length(secret_nonce) AS nonce_bytes, created_at, updated_at
FROM workflow_webhooks;

CREATE VIEW parity_workflows AS
SELECT id, tenant_id, regexp_replace(name, ' — [0-9A-F]{8}$', ' — <suffix>') AS name, description_text, enabled, draft_definition,
       draft_revision, published_version_id, is_legacy_job, legacy_skill_name, created_at, updated_at
FROM workflows;
